let
    Source = fxRead("SELECT s.receipt_id, s.po_line_id, s.receipt_date, s.received_kg, s.landed_unit_cost_eur, s.receipt_value_eur, s.purchase_unit_cost_eur, s.purchase_value_eur, s.inbound_freight_rate_eur_per_kg, s.inbound_freight_eur, s.landed_receipt_value_eur, s.material_id, s.supplier_id, s.order_date, s.expected_receipt_date, s.agreed_unit_cost_eur, s.material_name, s.supplier_name, s.on_time, s.actual_lead_time_days FROM manufacturing_v2.bi_procurement_receipts s"),
    Typed = Table.TransformColumnTypes(Source, {{"on_time", type logical}, {"order_date", type date}, {"po_line_id", type text}, {"receipt_id", type text}, {"material_id", type text}, {"received_kg", type number}, {"supplier_id", type text}, {"receipt_date", type date}, {"material_name", type text}, {"supplier_name", type text}, {"receipt_value_eur", Currency.Type}, {"purchase_value_eur", Currency.Type}, {"inbound_freight_eur", Currency.Type}, {"agreed_unit_cost_eur", type number}, {"landed_unit_cost_eur", type number}, {"actual_lead_time_days", Int64.Type}, {"expected_receipt_date", type date}, {"purchase_unit_cost_eur", type number}, {"landed_receipt_value_eur", Currency.Type}, {"inbound_freight_rate_eur_per_kg", type number}}, "en-US"),
    Added = Table.AddColumn(Typed, "ReceiptMonth", each Date.StartOfMonth([receipt_date]), type date)
in Added
